    },
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "Rarity of the drive-then-PNR sequence could yield insufficient statistical power, especially after any attempt to restrict to confident labels."
    },
    {
      "code": "OUTCOME_DERIVED_LABEL",
      "text": "The outcome, PNR PPP, is itself derived from the same labeling system, so any labeling error directly biases the target variable."
    }
  ],
  "predicted_outcome": {
    "supported": 0.02,
    "rejected": 0.03,
    "untestable": 0.25,
    "artifact": 0.60,
    "uncertain": 0.10
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "The difference in points per possession (PPP) for pick‑and‑roll (PNR) possessions that were immediately preceded by a teammate drive within the same possession, compared to PNR possessions without a preceding drive.",
    "unit": "A single offensive possession that contains an identified PNR and a preceding event.",
    "sample": "All possessions from the NBA 2025‑26 regular season and playoffs where a PNR is recorded and a possession‑level preceding event can be determined. Minimum viable subset would require manually validated labels for at least 2,000 such sequences.",
    "power": "To detect a 0.05 PPP difference with 80% power, approximately 2,000 qualifying possessions would be needed assuming a standard deviation of 0.9 PPP. The expected frequency of drive‑then‑PNR sequences is unknown but likely far lower, so adequate power is improbable.",
